import { formatPrice } from "../lib/format";

type ProductCardProps = {
  name: string;
  priceCents: number;
};

export function ProductCard({ name, priceCents }: ProductCardProps) {
  return (
    <article className="product-card">
      <h2>{name}</h2>
      <p>{formatPrice(priceCents)}</p>
    </article>
  );
}

import { useState } from "react";

export function AddToCart() {
  const [quantity, setQuantity] = useState(0);

  return (
    <button type="button" onClick={() => setQuantity(quantity + 1)}>
      In cart: {quantity}
    </button>
  );
}

import { AddToCart } from "./components/AddToCart";
import { ProductCard } from "./components/ProductCard";

const products = [
  { slug: "trail-pack-45", name: "Trail Pack 45L", priceCents: 18900 },
  { slug: "alpine-1p-tent", name: "Alpine 1P Tent", priceCents: 27900 },
  { slug: "camp-kettle-1l", name: "Camp Kettle 1L", priceCents: 3400 },
];

export default function App() {
  return (
    <main>
      <h1>Trailhead</h1>
      {products.map((product) => (
        <ProductCard key={product.slug} name={product.name} priceCents={product.priceCents} />
      ))}
      <AddToCart />
    </main>
  );
}
